import{_ as s,C as a,o as r,c as n,j as t,a as i,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const l="/screenshots/vscode-run-control.png",u="/diagrams/run-control.svg",y=JSON.parse(`{"title":"Pause and step from the editor","description":"Pause a test run Piwi started from VS Code or a JetBrains IDE, or one you started in a terminal, step it call by call, run it to the cursor, resume, finish or end it, with the paused line marked in the editor, your breakpoints applied as you change them, and a headless test's page shown as an image you pick a locator on.","frontmatter":{"title":"Pause and step from the editor","description":"Pause a test run Piwi started from VS Code or a JetBrains IDE, or one you started in a terminal, step it call by call, run it to the cursor, resume, finish or end it, with the paused line marked in the editor, your breakpoints applied as you change them, and a headless test's page shown as an image you pick a locator on.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-run-control.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-run-control.html"}],["meta",{"property":"og:title","content":"Pause and step from the editor | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Pause a test run Piwi started from VS Code or a JetBrains IDE, or one you started in a terminal, step it call by call, run it to the cursor, resume, finish or end it, with the paused line marked in the editor, your breakpoints applied as you change them, and a headless test's page shown as an image you pick a locator on."}]]},"headers":[],"relativePath":"features/editor-run-control.md","filePath":"features/editor-run-control.md","lastUpdated":1793392285000}`),c={name:"features/editor-run-control.md"};function p(g,e,w,m,f,b){const o=a("Needs");return r(),n("div",null,[e[0]||(e[0]=t("h1",{id:"pause-and-step-from-the-editor",tabindex:"-1"},[i("Pause and step from the editor "),t("a",{class:"header-anchor",href:"#pause-and-step-from-the-editor","aria-label":'Permalink to "Pause and step from the editor"'},"​")],-1)),h(o,{reporter:"",fixtures:""}),e[1]||(e[1]=d('<p>A test run the <a href="./editors.html">editor extensions</a> start can be paused, stepped and resumed from the editor, with Piwi&#39;s own commands: no debug session starts, and the IDE&#39;s debugger works as usual beside it; so can <a href="./terminal-runs.html">one you start in a terminal</a>. The editor marks the line the test stopped at, as a debugger does, and the breakpoints you set or remove reach the run while it goes on. The <a href="./editor-breakpoints.html#pause-a-run">pause bar</a> in the page answers the same stops, as does Piwi Picker&#39;s <a href="./runs-window.html">Runs window</a>. At a stop, the editor also writes code from the page: <a href="./editor-stop-code.html">Code from a pause</a>.</p><h2 id="the-controls" tabindex="-1">The controls <a class="header-anchor" href="#the-controls" aria-label="Permalink to &quot;The controls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th><th>VS Code</th><th>JetBrains IDEs</th></tr></thead><tbody><tr><td><strong>Pause</strong></td><td>Stops a running test before its next call that acts on, reads or checks the page</td><td>none</td><td>Resume Program&#39;s, <code>F9</code></td></tr><tr><td><strong>Resume</strong></td><td>Runs the stopped test on to the next breakpoint</td><td><code>F5</code></td><td>Resume Program&#39;s, <code>F9</code></td></tr><tr><td><strong>Step</strong></td><td>Runs the call and stops before the next one, breakpoint or not</td><td><code>F10</code></td><td>Step Over&#39;s, <code>F8</code></td></tr><tr><td><strong>Run to cursor</strong></td><td>Stops at the first call on the cursor&#39;s line, or at a breakpoint before it</td><td><code>Ctrl+F10</code></td><td>Run to Cursor&#39;s, <code>Alt+F9</code></td></tr><tr><td><strong>Finish</strong></td><td>Runs the test on without stopping at a breakpoint again in this attempt</td><td><code>Shift+F11</code></td><td>Step Out&#39;s, <code>Shift+F8</code></td></tr><tr><td><strong>End the test</strong></td><td><a href="./end-the-test.html">Skips the rest of the test</a>, the stopped call included</td><td>none</td><td>none</td></tr><tr><td><strong>Stop</strong></td><td>Ends the run&#39;s process</td><td><code>Shift+F5</code></td><td>the Run tool window&#39;s Stop</td></tr></tbody></table><p>The keys are the IDE&#39;s own debugger keys (in a JetBrains IDE, your keymap&#39;s), Piwi&#39;s only while their control applies and no debug session runs, and first where a JetBrains keymap gives one to another action too. On macOS, <code>Cmd+F10</code> runs to the cursor in VS Code. <strong>Pause</strong> and <strong>End the test</strong> have no key in VS Code: bind one in <strong>Preferences: Open Keyboard Shortcuts</strong> (search <code>piwi</code>). There, <code>F5</code> pressed again within two seconds of an answer waits for the next stop rather than start a debug session.</p><ul><li><strong>In VS Code</strong>, the controls sit in the status bar beside the run&#39;s progress while they apply (<code>Pausing…</code> until a paused test stops), and in the palette (<strong>Piwi: Pause the run</strong> and its kin, <strong>Piwi: Show the paused page</strong>).</li><li><strong>In a JetBrains IDE</strong>, they are under <strong>Tools → Piwi</strong>, enabled while they apply, and first in the status bar item&#39;s menu, which reads <code>Piwi: paused · checkout.page.ts:12</code> while a test is stopped.</li></ul><p><strong>Pause</strong> stops every run Piwi started in this window (in a JetBrains IDE, this project), each worker before its next call that Playwright&#39;s debugger stops at (<a href="./editor-breakpoints.html#limits">which calls</a>): a long call or a <code>waitForTimeout</code> finishes first, and a worker between tests stops at the next test&#39;s first call. A test that never stops, under CI or Playwright&#39;s own debugger, says why.</p><h2 id="where-the-test-stands" tabindex="-1">Where the test stands <a class="header-anchor" href="#where-the-test-stands" aria-label="Permalink to &quot;Where the test stands&quot;">​</a></h2><p>When a test stops, at a breakpoint, after <strong>Step</strong> or <strong>Pause</strong>, on the line it was run to, at <code>page.pause()</code>, or at <a href="./editor-stop-code.html#a-failure">a failure</a>, the editor opens the file of the call about to run, with the cursor on its line, and marks it: an arrow in the gutter, the debugger&#39;s execution point color, and above it the call, as Playwright names it, with the controls:</p><p><code>Paused · Fill &quot;MORNING10&quot; getByLabel(&#39;Coupon code&#39;) · attempt 2</code> Resume Step Run to cursor Finish End test</p><p><code>attempt 2</code> shows on a retry. In VS Code the line is a CodeLens, the marked line&#39;s hover holding the controls; the color is <code>piwi.executionPointBackground</code>. In a JetBrains IDE the line is an inlay whose words are links, the arrow&#39;s click lists the controls, and the color is <strong>Settings → Editor → Color Scheme → Piwi → Line a run is stopped at</strong>. The mark goes when the test goes on (from the editor or the bar), ends, or closes its page.</p><figure><img src="'+l+'" alt="VS Code: a test paused at a page object&#39;s line, the controls above it and in the status bar"><figcaption>A run paused before it types the coupon.</figcaption></figure><p>With several workers stopped, each has its own mark, and the controls above a line act on its worker; a key or command acts on the one at the cursor&#39;s line, else asks which. A control answers the stop it was shown for: when the test went on meanwhile, it says so and asks nothing.</p><p>The run&#39;s code is your files as they stood when it started. The mark follows lines you add or remove above it, and <strong>Run to cursor</strong> in an edited file runs to the run&#39;s line for the cursor&#39;s; on a line written since, it says the test has none.</p><h2 id="a-headless-run" tabindex="-1">A headless run <a class="header-anchor" href="#a-headless-run" aria-label="Permalink to &quot;A headless run&quot;">​</a></h2><p>A run Piwi starts with breakpoints is headed, so the pause bar answers its stops too. One started without runs as its config says, headless by default: when you pause it, or it reaches a breakpoint set since, no bar shows, and the editor shows an image of the page at the stop: in VS Code in a <strong>Piwi: paused page</strong> tab beside the editor, in a JetBrains IDE in the Piwi tool window&#39;s <strong>Paused Page</strong> tab. <strong>Piwi: Show the paused page</strong> (<strong>Tools → Piwi → Show the Paused Page</strong>) asks for it at any stop.</p><p>With a reporter newer than 0.61.0, the image says <strong>Click the image to pick a locator</strong>. A click picks the element under it, as the bar&#39;s <strong>Pick a locator</strong> does, without touching the page: its locator replaces the one on the stopped line, and the tab says so, or why not. In VS Code, a script in the tab sends the editor the click&#39;s position alone.</p><h2 id="breakpoints-while-the-run-goes-on" tabindex="-1">Breakpoints while the run goes on <a class="header-anchor" href="#breakpoints-while-the-run-goes-on" aria-label="Permalink to &quot;Breakpoints while the run goes on&quot;">​</a></h2><p>A breakpoint you add, remove or toggle applies to the run from its next call, in each of its workers, later ones included. One that only moves because you edited the lines above it keeps the line the run has, and one you set in an edited file applies to that line of the run&#39;s code. The breakpoints that count are those a run&#39;s start reads: line breakpoints in script files under a Playwright config&#39;s folder, while <code>piwi.breakpoints</code> (<strong>Pause the runs Piwi starts at the editor&#39;s breakpoints</strong> in a JetBrains IDE) is on.</p><h2 id="share-live" tabindex="-1">Share live <a class="header-anchor" href="#share-live" aria-label="Permalink to &quot;Share live&quot;">​</a></h2><p><strong>Share live</strong> lets a teammate watch the run from its page on your team&#39;s instance: <strong>Piwi: Share the run live on the team instance</strong> in VS Code, <strong>Tools → Piwi → Share the Run Live</strong> in a JetBrains IDE, any time. It first says what goes out and to whom (once a VS Code window, once a JetBrains project); shared, the status bar counts its views, until <strong>Stop sharing</strong>: <a href="./live-view.html#share-a-run-from-your-machine">Share a run from your machine</a>.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><figure><img src="'+u+'" alt="A test run&#39;s workers report to the editor service through the run channel, which the IDE and Piwi Picker (over a WebSocket) steer; the pause bar shows in the test&#39;s browser only at a stop"></figure><p>With a reporter newer than 0.59.0, each worker of a Piwi run stays connected to the editor service, through a socket on your machine only you can read (<code>PIWI_RUN_CHANNEL</code>): it says which test it runs and where it stops, and the editor answers. Closing the IDE closes the connections: a stop with no pause bar then goes on, one the bar shows waits there.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Runs Piwi can follow.</strong> A run started by the IDE&#39;s own Playwright run configuration has no controls in the editor; with <strong>Run the tests in the IDE&#39;s Playwright runner</strong> on, a JetBrains IDE&#39;s runs keep them, their Rerun, Rerun Failed Tests and Debug included.</li><li><strong>No mark on a breakpoint that never stops.</strong> One on a line with no call Playwright&#39;s debugger stops at looks like any other and does nothing.</li><li><strong>Playwright calls, not JavaScript.</strong> <strong>Step</strong> goes from one Playwright call to the next; stepping through the test&#39;s own code stays with the IDE&#39;s debugger.</li><li><strong>A still image.</strong> It does not follow the page: the <a href="./runs-window.html#watch-live">Runs window</a> shows it live.</li><li><strong>No image when the page is unknown.</strong> A stop at a call other than a locator&#39;s (a navigation, a key press) in a browser context with several pages has no image, and refuses Piwi Picker&#39;s <strong>Pick</strong> and <strong>Record</strong>: the worker cannot tell its page. Any page of that context closing ends it.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-breakpoints.html">Breakpoints in the browser</a>: the breakpoints a run starts with, and the pause bar.</li><li><a href="./editor-runs.html">Runs from the editor</a>: the commands that start a run, and how the editor follows it.</li><li><a href="./debug-in-editor.html">Debug in my editor</a>: such a run, started from a failure&#39;s page.</li><li><a href="./editors.html">Editor extensions</a>: what the editor shows from your suite, in both editors.</li><li><a href="/guide/remote-development.html">Remote development</a>: remote windows and JetBrains Gateway.</li></ul>',27))])}const P=s(c,[["render",p]]);export{y as __pageData,P as default};
